// Generates bend/lib/markup.bend from markup/*.html: the modals the original
// UpperContent.js wrote and the layouts of InnerContent.js and
// InnerContent-02.js.   bun tools/gen-markup.mjs
import fs from "node:fs";

const read = (name) => fs.readFileSync(new URL(`../markup/${name}`, import.meta.url), "utf8").replace(/\n$/, "");
const out = `# Markup: the page's modals and layouts, from markup/*.html.
# Generated by tools/gen-markup.mjs; edit the HTML files, not this file.
import Base

def upper() -> String:
  ${JSON.stringify(read("upper.html"))}

def inner() -> String:
  ${JSON.stringify(read("inner.html"))}

def inner_02() -> String:
  ${JSON.stringify(read("inner-02.html"))}
`;
fs.writeFileSync(new URL("../bend/lib/markup.bend", import.meta.url), out);
console.log("markup.bend written");
